const joobaLW = {
    joobaMountWheel: () => { },
    mountMultipleWheels: () => { },
    spinWheel: () => { },
    wheels: [],
    spinMultipleWheelsSequentially: () => { },
}

function loadDependencies() {
    const gsap = document.createElement('script')
    gsap.src = 'https://cdnjs.cloudflare.com/ajax/libs/gsap/3.10.1/gsap.min.js'
    gsap.onload = function () {
        console.log('GSAP is loaded!')
    }
    document.head.appendChild(gsap)
}

function joobaMountWheel({
    wheelIndex,
    wheelSegments: segments,
    wheelSize = 300,
    scale: scaleP,
    order,
    backgroundImage,
    borderImage,
    selectorImage,
    selectorPosition,
    selectorScale,
    wheelSegments,
}) {
    const scale = (scaleP / 100) || 1
    const wholeWrapper = document.createElement('div')
    wholeWrapper.style.position = 'absolute'
    wholeWrapper.style.top = `${wheelSize / 2}px`
    wholeWrapper.style.left = `${wheelSize / 2}px`
    wholeWrapper.style.transform = 'translate(-50%,-50%)'

    const zIndexBase = wheelIndex + 1

    const wheelWrapper = document.createElement('div')
    wheelWrapper.id = `jooba-wheel-wrapper-${wheelIndex}`
    wheelWrapper.style.width = `${wheelSize * scale}px`
    wheelWrapper.style.height = `${wheelSize * scale}px`
    wheelWrapper.style.overflow = 'hidden'

    wheelWrapper.style.position = 'relative'

    wheelWrapper.style.zIndex = zIndexBase

    const wheelBorder = document.createElement('div')
    wheelBorder.id = `jooba-wheel-border-${wheelIndex}`

    if (borderImage) {
        wheelBorder.style.position = 'absolute'
        wheelWrapper.style.zIndex = zIndexBase + 2
        wheelBorder.style.top = '0px'
        wheelBorder.style.left = '0px'
        wheelBorder.style.width = `${wheelSize * scale}px`
        wheelBorder.style.height = `${wheelSize * scale}px`
        wheelBorder.style.background = `url(${borderImage})`
        wheelBorder.style.backgroundSize = '100% 100%'
        wheelBorder.style.backgroundPosition = 'center center'
    }

    const wheelSelector = document.createElement('div')
    wheelSelector.id = `jooba-wheel-selector-${wheelIndex}`

    if (selectorImage) {
        wheelBorder.style.position = 'absolute'
        wheelBorder.style.top = '0px'
        wheelBorder.style.left = '0px'
        wheelWrapper.style.zIndex = zIndexBase + 3
        wheelSelector.style.width = `${wheelSize * scale}px`
        wheelSelector.style.height = `${wheelSize * scale}px`

        const wheelSelectorImage = document.createElement('img')
        wheelSelectorImage.src = selectorImage
        wheelSelectorImage.style.width = `${wheelSize * scale * 0.5 * (((selectorScale / 100) || 0.1) || 0.1)}px`
        wheelSelectorImage.style.height = `${wheelSize * scale * 0.5 * (((selectorScale / 100) || 0.1) || 0.1)}px`

        if (selectorPosition === 'center') {
            wheelSelectorImage.style.marginLeft = `${(wheelSize / 2) * scale}px`
            wheelSelectorImage.style.marginTop = `${(wheelSize / 2) * scale}px`
            wheelSelectorImage.style.transform = 'translate(-50%, -50%)'
        }
        if (selectorPosition === 'top') {
            wheelSelectorImage.style.marginLeft = `${(wheelSize / 2) * scale}px`
            wheelSelectorImage.style.marginTop = `${(wheelSize * 0.01) * scale}px`
            wheelSelectorImage.style.transform = 'translateX(-50%)'
        }
        wheelSelector.appendChild(wheelSelectorImage)
    }

    const wheelContainer = document.createElement('div')

    wheelContainer.style.position = 'absolute'
    wheelContainer.style.top = '0px'
    wheelContainer.style.left = '0px'
    wheelWrapper.style.zIndex = zIndexBase + 1
    wheelContainer.style.width = `${wheelSize * scale}px`
    wheelContainer.style.height = `${wheelSize * scale}px`
    wheelContainer.style.borderRadius = '50% 50%'
    wheelContainer.style.overflow = 'hidden'

    if (backgroundImage) {
        wheelContainer.style.background = `url(${backgroundImage})`
        wheelContainer.style.backgroundSize = '100% 100%'
        wheelContainer.style.backgroundPosition = 'center center'
    }
    wheelContainer.id = `jooba-wheel-${wheelIndex}`

    const wheel = document.createElement('div')
    const pie = document.createElement('div')
    pie.setAttribute('id', 'jooba-pie-spin')
    pie.setAttribute('class', 'jooba-pie')

    wheel.innerHTML = ''
    wheel.appendChild(pie)
    wheel.setAttribute('class', 'jooba-wheel')
    wheelContainer.appendChild(wheel)

    function createPieSegments() {
        pie.innerHTML = ''
        pie.setAttribute('data-segments', `${segments.length}`)
        segments.forEach((slice, i) => {
            const value = 100 / segments.length
            const offset = value * i
            const pieSegment = document.createElement('div')
            pieSegment.classList.add('jooba-pie-segment')
            pieSegment.style.setProperty('--offset', offset)
            pieSegment.style.setProperty('--value', value)
            pieSegment.style.setProperty('--bg', slice.icon)
            pieSegment.style.setProperty('--bgc', slice.colour)

            const contentElementWrapper = document.createElement('div')
            contentElementWrapper.classList.add('jooba-pie-segment-element-wrapper')
            contentElementWrapper.classList.add(`jooba-pie-segment-element-wrapper${i}`)

            if (slice.icon) {
                const iconElement = document.createElement('img')
                iconElement.classList.add('jooba-pie-segment-icon')
                iconElement.classList.add(`jooba-pie-segment-icon-${i}`)
                iconElement.style.setProperty('color', slice.color)
                iconElement.setAttribute('src', slice.icon)
                if (slice.style?.left) {
                    pieSegment.style.setProperty('--left', `${slice.style?.left}%`)
                }
                if (slice.style?.bottom) {
                    pieSegment.style.setProperty('--bottom', `${slice.style?.bottom}%`)
                }
                if (slice.style?.width) {
                    pieSegment.style.setProperty('--width', `${slice.style?.width}%`)
                }
                contentElementWrapper.appendChild(iconElement)
                pieSegment.appendChild(contentElementWrapper)
            }
            pie.appendChild(pieSegment)
        })
    }

    function updateSize() {
        const size = wheelSize
        pie.style.setProperty('--size', `${size}px`)
        pie.style.height = `${size}px`
        pie.style.width = `${size}px`
    }

    updateSize()
    createPieSegments()
    wheelWrapper.appendChild(wheelContainer)
    wheelWrapper.appendChild(wheelBorder)
    wheelWrapper.appendChild(wheelSelector)
    wholeWrapper.appendChild(wheelWrapper)

    return {
        wrapper: wholeWrapper,
        border: wheelBorder,
        selector: wheelSelector,
        wheel: wheelContainer,
    }
}

function spinWheel(props) {
    const {
        wheel,
        winnerIndex,
        spins = 10,
        duration = 5,
        bounce = {
            amplitude: 2,
            frequency: 0.35,
        },
        onComplete = () => { },
    } = props
    const segments = wheel.querySelectorAll('.jooba-pie-segment')
    const totalSegments = segments.length
    const degreesPerSegment = 360 / totalSegments
    const fullCircleDegrees = spins * 360
    const winnerDegree = (winnerIndex * degreesPerSegment)
    const winnerPosition = winnerDegree + (degreesPerSegment * 0.5)
    const finalPosition = fullCircleDegrees - winnerPosition

    const tl = window.gsap.timeline()
    tl
        .to(wheel, 0.0, {
            rotation: '0deg',
            ease: 'none',
            force3D: true,
        })
        .to(wheel, {
            rotation: `+=${finalPosition}`,
            duration,
            ease: `elastic.out(${bounce.amplitude},${bounce.frequency})`,
            force3D: true,
            onComplete: () => {
                console.log(`Winner is segment ${winnerIndex}`)
                onComplete()
            },
        }).to(wheel, 0.5, {
            rotation: '+=2',
            ease: 'power2.out',
            force3D: true,
        }, '-=0.5')
}

function mountMultipleWheels({ container, configurations, wrapperSize }) {
    container.innerHTML = ''
    joobaLW.wheels = []
    const wrapperWheels = document.createElement('div')
    wrapperWheels.setAttribute('class', 'jooba-wrapper-wheels')
    wrapperWheels.style.width = `${wrapperSize}px`
    wrapperWheels.style.height = `${wrapperSize}px`

    configurations.tiers.forEach((config, index) => {
        const wheelMounted = joobaMountWheel({
            ...config,
            wheelIndex: index,
            wheelSize: wrapperSize,
        })
        joobaLW.wheels.push(wheelMounted)
        wrapperWheels.appendChild(wheelMounted.wrapper)
    })
    container.appendChild(wrapperWheels)
    return joobaLW.wheels
}

async function spinMultipleWheelsSequentially(wheelConfigs) {
    function spin(spinConfig) {
        console.log('spinConfig: ', spinConfig)
        return new Promise((resolve) => {
            window.joobaLW.spinWheel({
                wheel: spinConfig.wheel,
                winnerIndex: spinConfig.winnerIndex,
                spins: spinConfig.spins,
                duration: spinConfig.duration,
                ...spinConfig,
                onComplete: resolve,
            })
        })
    }

    await wheelConfigs.reduce((promiseChain, spinConfig) => {
        return promiseChain.then(() => spin(spinConfig))
    }, Promise.resolve())
}

joobaLW.mount = joobaMountWheel
joobaLW.mountMultipleWheels = mountMultipleWheels
joobaLW.spinWheel = spinWheel
joobaLW.wheels = []
joobaLW.spinMultipleWheelsSequentially = spinMultipleWheelsSequentially

loadDependencies()
window.joobaLW = joobaLW
